async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }
  try {
    const options: SessionListOptions = {
      ...(message.limit !== undefined ? {limit: message.limit} : {}),
      ...(message.before !== undefined ? {before: message.before} : {}),
    };
    const hasOptions = 'limit' in options || 'before' in options;
    const list = await sessionStore.listFor(session.userId, hasOptions ? options : undefined);
    const sessions: SessionSummaryFrame[] = list.map(summary => ({
      sessionId: summary.sessionId,
      createdAt: summary.createdAt instanceof Date ? summary.createdAt.toISOString() : String(summary.createdAt),
      updatedAt: summary.updatedAt instanceof Date ? summary.updatedAt.toISOString() : String(summary.updatedAt),
      entryCount: summary.entryCount,
    }));
    sendSessionList(ws, sessions);
  } catch (error) {
    const errMessage = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'failed to list conversations', {userId: session.userId, error: errMessage});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

